INSERT OR IGNORE INTO pay_statutory_params (company_id, doc_no, code, state_code, params_json, effective_from, legal_ref, status, approved_by, approved_at, created_by, source_type) VALUES (NULL, 'SYS/MIN_WAGE/ALL/2025-11-21', 'MIN_WAGE', 'ALL', '{"payDueDays": {"WEEKLY": 0, "FORTNIGHTLY": 2, "MONTHLY": 7}, "deductionCapPct": 50, "verifyDays": 3}', '2025-11-21', 'Code on Wages, 2019 s.17(1) (time of payment: weekly before the weekly holiday, fortnightly within 2 days, monthly within 7 days of the end of the period) and s.18(2) (deductions not above 50 % of the wages); CLRA Central Rules r.63. The minimum rates are the dated state master of 07.08 (lab_wage_rates).', 'APPROVED', 'migration', '2026-11-19T00:00:00.000Z', 'migration', 'reference_seed');
